反射和特性是 .NET 中强大的元编程能力，它们允许我们在运行时检查类型信息和为代码添加元数据。

## 特性（Attribute）

特性是一种为代码元素添加元数据的方式，使用方括号语法：
```csharp
[Serializable]
public class Person
{
    [Required(ErrorMessage = "姓名不能为空")]
    [StringLength(50)]
    public string Name { get; set; }

    [Obsolete("请使用 NewMethod")]
    public void OldMethod() { }
}
```

**常用内置特性**：
- `[Serializable]` - 标记类型可序列化
- `[Obsolete]` - 标记过时的代码
- `[AttributeUsage]` - 定义自定义特性的使用范围
- `[Conditional]` - 条件编译
- `[CallerMemberName]` - 自动获取调用者信息

**自定义特性**：
```csharp
[AttributeUsage(AttributeTargets.Class | AttributeTargets.Method, AllowMultiple = true)]
public class CacheAttribute : Attribute
{
    public int Duration { get; set; }
    public string Key { get; set; }

    public CacheAttribute(int duration)
    {
        Duration = duration;
    }
}

// 使用
[Cache(300, Key = "user")]
public class UserService { }
```

## 反射（Reflection）

反射提供了在运行时检查和操作类型的能力：

**获取类型信息**：
```csharp
Type type = typeof(Person);
// 或
Type type = person.GetType();

// 获取类型信息
Console.WriteLine(type.Name); // Person
Console.WriteLine(type.FullName); // Namespace.Person
Console.WriteLine(type.IsClass); // True
Console.WriteLine(type.IsPublic); // True
```

**检查成员**：
```csharp
// 获取所有公共属性
PropertyInfo[] properties = type.GetProperties();
foreach (var prop in properties)
{
    Console.WriteLine($"{prop.Name}: {prop.PropertyType}");
}

// 获取特定成员
MethodInfo method = type.GetMethod("GetName");
ConstructorInfo ctor = type.GetConstructor(new[] { typeof(string) });
```

**动态调用**：
```csharp
// 创建实例
object instance = Activator.CreateInstance(type);
// 或带参数
object instance = Activator.CreateInstance(type, "Alice", 25);

// 设置属性
PropertyInfo nameProp = type.GetProperty("Name");
nameProp.SetValue(instance, "Bob");

// 调用方法
MethodInfo method = type.GetMethod("GetName");
string result = (string)method.Invoke(instance, null);
```

**检查特性**：
```csharp
// 检查类型上的特性
var cacheAttr = type.GetCustomAttribute<CacheAttribute>();
if (cacheAttr != null)
{
    Console.WriteLine($"缓存时长: {cacheAttr.Duration}");
}

// 检查所有特性
object[] attrs = type.GetCustomAttributes(false);
foreach (var attr in attrs)
{
    Console.WriteLine(attr.GetType().Name);
}
```

using System;
using System.Collections.Generic;
using System.Linq;
using System.Linq.Expressions;
using System.Reflection;

namespace ReflectionAttributesDemo
{
    // 自定义特性
    [AttributeUsage(AttributeTargets.Class | AttributeTargets.Property, AllowMultiple = true)]
    public class CacheAttribute : Attribute
    {
        public int Duration { get; set; }
        public string Region { get; set; }

        public CacheAttribute(int duration)
        {
            Duration = duration;
        }
    }

    [AttributeUsage(AttributeTargets.Property)]
    public class RequiredAttribute : Attribute
    {
        public string ErrorMessage { get; set; }
    }

    [AttributeUsage(AttributeTargets.Property)]
    public class MaxLengthAttribute : Attribute
    {
        public int Length { get; set; }

        public MaxLengthAttribute(int length)
        {
            Length = length;
        }
    }

    // 使用特性
    [Cache(300, Region = "users")]
    public class User
    {
        [Required(ErrorMessage = "ID 不能为空")]
        public int Id { get; set; }

        [Required(ErrorMessage = "姓名不能为空")]
        [MaxLength(50)]
        public string Name { get; set; }

        [MaxLength(100)]
        public string Email { get; set; }

        public DateTime CreatedAt { get; set; }

        [Cache(60)]
        public string GetDisplayName() => $"{Name} ({Id})";
    }

    // 反射工具类
    public static class ReflectionHelper
    {
        // 缓存类型信息
        private static readonly Dictionary<Type, PropertyInfo[]> PropertyCache = new();

        public static PropertyInfo[] GetCachedProperties(Type type)
        {
            if (!PropertyCache.TryGetValue(type, out var properties))
            {
                properties = type.GetProperties(BindingFlags.Public | BindingFlags.Instance);
                PropertyCache[type] = properties;
            }
            return properties;
        }

        // 获取特性
        public static T GetAttribute<T>(MemberInfo member) where T : Attribute
        {
            return member.GetCustomAttribute<T>();
        }

        // 验证对象
        public static List<string> Validate(object obj)
        {
            var errors = new List<string>();
            var type = obj.GetType();
            var properties = GetCachedProperties(type);

            foreach (var prop in properties)
            {
                var requiredAttr = prop.GetCustomAttribute<RequiredAttribute>();
                if (requiredAttr != null)
                {
                    var value = prop.GetValue(obj);
                    if (value == null || string.IsNullOrWhiteSpace(value.ToString()))
                    {
                        errors.Add(requiredAttr.ErrorMessage ?? $"{prop.Name} 不能为空");
                    }
                }

                var maxLengthAttr = prop.GetCustomAttribute<MaxLengthAttribute>();
                if (maxLengthAttr != null && prop.PropertyType == typeof(string))
                {
                    var value = prop.GetValue(obj) as string;
                    if (value != null && value.Length > maxLengthAttr.Length)
                    {
                        errors.Add($"{prop.Name} 长度不能超过 {maxLengthAttr.Length}");
                    }
                }
            }

            return errors;
        }

        // 动态创建对象
        public static T CreateInstance<T>(params object[] args)
        {
            return (T)Activator.CreateInstance(typeof(T), args);
        }

        // 深拷贝
        public static T DeepCopy<T>(T source)
        {
            var type = source.GetType();
            var target = Activator.CreateInstance(type);
            var properties = GetCachedProperties(type);

            foreach (var prop in properties)
            {
                if (prop.CanRead && prop.CanWrite)
                {
                    var value = prop.GetValue(source);
                    prop.SetValue(target, value);
                }
            }

            return (T)target;
        }
    }

    // Expression Tree 示例
    public static class ExpressionHelper
    {
        // 动态排序
        public static IQueryable<T> OrderByDynamic<T>(
            IQueryable<T> query,
            string propertyName,
            bool ascending = true)
        {
            var parameter = Expression.Parameter(typeof(T), "x");
            var property = Expression.Property(parameter, propertyName);
            var lambda = Expression.Lambda(property, parameter);

            var methodName = ascending ? "OrderBy" : "OrderByDescending";
            var method = typeof(Queryable).GetMethods()
                .First(m => m.Name == methodName && m.GetParameters().Length == 2)
                .MakeGenericMethod(typeof(T), property.Type);

            return (IQueryable<T>)method.Invoke(null, new object[] { query, lambda });
        }

        // 动态过滤
        public static IQueryable<T> WhereDynamic<T>(
            IQueryable<T> query,
            string propertyName,
            object value)
        {
            var parameter = Expression.Parameter(typeof(T), "x");
            var property = Expression.Property(parameter, propertyName);
            var constant = Expression.Constant(value);
            var equality = Expression.Equal(property, constant);
            var lambda = Expression.Lambda<Func<T, bool>>(equality, parameter);

            return query.Where(lambda);
        }

        // 创建属性访问器
        public static Func<T, object> CreatePropertyAccessor<T>(string propertyName)
        {
            var parameter = Expression.Parameter(typeof(T), "x");
            var property = Expression.Property(parameter, propertyName);
            var convert = Expression.Convert(property, typeof(object));
            var lambda = Expression.Lambda<Func<T, object>>(convert, parameter);

            return lambda.Compile();
        }
    }

    class Program
    {
        static void Main()
        {
            // 反射使用示例
            var user = new User { Id = 1, Name = "Alice", Email = "alice@example.com" };

            // 验证
            var errors = ReflectionHelper.Validate(user);
            Console.WriteLine($"验证错误: {errors.Count}");

            // 获取特性信息
            var type = typeof(User);
            var cacheAttr = type.GetCustomAttribute<CacheAttribute>();
            Console.WriteLine($"缓存时长: {cacheAttr.Duration}, 区域: {cacheAttr.Region}");

            // 动态创建对象
            var newUser = ReflectionHelper.CreateInstance<User>();

            // 深拷贝
            var clonedUser = ReflectionHelper.DeepCopy(user);

            // Expression Tree 示例
            var users = new List<User>
            {
                new User { Id = 3, Name = "Charlie" },
                new User { Id = 1, Name = "Alice" },
                new User { Id = 2, Name = "Bob" }
            }.AsQueryable();

            // 动态排序
            var sorted = ExpressionHelper.OrderByDynamic(users, "Name");
            foreach (var u in sorted)
            {
                Console.WriteLine($"{u.Id}: {u.Name}");
            }

            // 动态过滤
            var filtered = ExpressionHelper.WhereDynamic(users, "Id", 2);
            Console.WriteLine($"过滤结果: {filtered.First().Name}");

            // 创建属性访问器
            var nameAccessor = ExpressionHelper.CreatePropertyAccessor<User>("Name");
            Console.WriteLine($"访问器结果: {nameAccessor(user)}");
        }
    }
}
